module EvenCounter {

  // Helper lemma to prove properties about multiplication
  lemma mult_fair(x: int, y: int)
    requires x >= 0 && y >= 0
    ensures x * y >= 0
  {
    // Multiplication of non-negative numbers is non-negative
  }

  // Helper lemma to prove properties about even numbers
  lemma evenest_positive(n: int)
    requires n >= 0
    ensures n % 2 == 0 ==> n >= 0
  {
    // Even non-negative numbers are non-negative
  }

  // Helper lemma for accumulation properties
  lemma accum_property(arr: seq<int>, pos: int, count: int)
    requires 0 <= pos <= |arr|
    requires count >= 0
    ensures count >= 0
  {
    // Count remains non-negative
  }

  // Recursive method to count even numbers up to index i
  method Count(seq: seq<int>, i: int) returns (count: int)
    requires 0 <= i <= |seq|
    ensures count == |seq[..i] filter x => x % 2 == 0|
    decreases i
  {
    if i == 0 {
      count := 0;
    } else {
      var prev := Count(seq, i - 1);
      if seq[i - 1] % 2 == 0 {
        count := prev + 1;
      } else {
        count := prev;
      }
    }
  }

  // Method to compute cumulative counts using Count
  method FooCount(seq: seq<int>) returns (result: array<int>)
    requires |seq| > 0
    ensures result.Length == |seq|
    ensures forall j :: 0 <= j < result.Length ==> 
            result[j] == |seq[..j+1] filter x => x % 2 == 0|
  {
    result := new int[|seq|];
    var i := 0;

    while i < result.Length
      invariant 0 <= i <= result.Length
      invariant result.Length == |seq|
      invariant forall j :: 0 <= j < i ==> 
               result[j] == |seq[..j+1] filter x => x % 2 == 0|
    {
      result[i] := Count(seq, i + 1);
      i := i + 1;
    }
  }

  // Alternative implementation that computes counts directly
  method ComputeCount(seq: seq<int>) returns (result: array<int>)
    requires |seq| > 0
    ensures result.Length == |seq|
    ensures forall j :: 0 <= j < result.Length ==> 
            result[j] == |seq[..j+1] filter x => x % 2 == 0|
  {
    result := new int[|seq|];
    var cumulative := 0;
    var i := 0;

    while i < result.Length
      invariant 0 <= i <= result.Length
      invariant cumulative == |seq[..i] filter x => x % 2 == 0|
      invariant forall j :: 0 <= j < i ==> 
               result[j] == |seq[..j+1] filter x => x % 2 == 0|
    {
      if seq[i] % 2 == 0 {
        cumulative := cumulative + 1;
      }
      result[i] := cumulative;
      i := i + 1;
    }
  }

