    if ref_pos > enumerable_length || ref_count < 0 {
      unexpected := true;
    } else {
      unexpected := false;
    }

    // Verify properties
    assert_(ref_pos >= 0);
    assert_(ref_count >= 0);
    assert_(enumerable_length >= 0);
  }

  // Helper method for assertions
  method assert_(condition: bool)
    requires condition
  {
    // This method only verifies if the condition is true
  }

  // Test method to demonstrate functionality
  method Test() 
  {
    var test_seq := [1, 2, 3, 4, 5, 6];

    // Test Count method
    var count1 := Count(test_seq, 3);
    assert_(count1 == 1); // Only 2 is even in first 3 elements

    var count2 := Count(test_seq, 6);
    assert_(count2 == 3); // 2, 4, 6 are even

    // Test FooCount
    var result1 := FooCount(test_seq);
    assert_(result1[0] == 0); // 1 is odd
    assert_(result1[1] == 1); // 1,2 -> 2 is even
    assert_(result1[5] == 3); // All elements -> 3 evens

    // Test ComputeCount
    var result2 := ComputeCount(test_seq);
    assert_(result2[0] == 0);
    assert_(result2[1] == 1);
    assert_(result2[5] == 3);

    // Test accum_generate
    var arr := new int[10];
    var unexpected1 := accum_generate(arr, 5, 3, 10);
    assert_(!unexpected1);

    var unexpected2 := accum_generate(arr, 15, 3, 10);
    assert_(unexpected2);

    // Verify mult and evenest properties
    var x := 5;
    var y := 3;
    mult_fair(x, y);

    var n := 4;
    evenest_positive(n);

    // Test accum_property
    accum_property(test_seq, 3, 2);

    print "All tests passed!\n";
  }

  // Main method to run the test
  method Main() {
    Test();
  }
}
