method CountExample<T(==)>(s: seq<T>, x: T) returns (count: nat)
  ensures count == |s[x := true]|
  ensures count == multiset(s)[x]
{
  count := 0;
  var i := 0;

  while i < |s|
    invariant 0 <= i <= |s|
    invariant count == |s[..i][x := true]|
  {
    if s[i] == x {
      count := count + 1;
    }
    i := i + 1;
  }
}

method CountProperties<T(==)>(s: seq<T>, x: T, y: T)
  requires x != y
{
  var count_x := CountExample(s, x);
  var count_y := CountExample(s, y);

  // Prove that counting x and y gives disjoint results
  assert count_x + count_y <= |s|;

  // Another property: if we replace x with y, count of x decreases
  var s2 := seq(|s|, i requires 0 <= i < |s| => if s[i] == x then y else s[i]);
  var count_x2 := CountExample(s2, x);
  assert count_x2 <= count_x;
}

method ArrayCountExample<T(==)>(a: array<T>, x: T) returns (count: nat)
  requires a != null
  ensures count == multiset(a[..])[x]
{
  count := 0;
  var i := 0;

  while i < a.Length
    invariant 0 <= i <= a.Length
    invariant count == multiset(a[..i])[x]
  {
    if a[i] == x {
      count := count + 1;
    }
    i := i + 1;
  }
}

method PartitionCount<T(==)>(s: seq<T>, pivot: T) 
  returns (less: seq<T>, equal: seq<T>, greater: seq<T>)
  ensures |s| == |less| + |equal| + |greater|
  ensures multiset(s) == multiset(less + equal + greater)
  ensures forall z :: z in less ==> z < pivot
  ensures forall z :: z in equal ==> z == pivot
  ensures forall z :: z in greater ==> z > pivot
{
  less := [];
  equal := [];
  greater := [];

  var i := 0;
  while i < |s|
    invariant 0 <= i <= |s|
    invariant |s| == |less| + |equal| + |greater| + (|s| - i)
    invariant multiset(s[..i]) == multiset(less + equal + greater)
    invariant forall z :: z in less ==> z < pivot
    invariant forall z :: z in equal ==> z == pivot
    invariant forall z :: z in greater ==> z > pivot
  {
    if s[i] < pivot {
      less := less + [s[i]];
    } else if s[i] == pivot {
      equal := equal + [s[i]];
    } else {
      greater := greater + [s[i]];
    }
    i := i + 1;
  }
}

method CountingSort(a: array<int>) 
  requires a != null
  modifies a
  ensures sorted(a[..])
  ensures multiset(a[..]) == multiset(old(a[..]))
{
