  var max := a[0];
  var i := 1;
  while i < a.Length
    invariant 1 <= i <= a.Length
    invariant forall j :: 0 <= j < i ==> min <= a[j] <= max
    invariant exists j :: 0 <= j < i && a[j] == min
    invariant exists j :: 0 <= j < i && a[j] == max
  {
    if a[i] < min { min := a[i]; }
    if a[i] > max { max := a[i]; }
    i := i + 1;
  }

  var range := max - min + 1;
  var count := new int[range];
  var k := 0;

  // Initialize count array
  while k < range
    invariant 0 <= k <= range
    invariant forall j :: 0 <= j < k ==> count[j] == 0
  {
    count[k] := 0;
    k := k + 1;
  }

  // Count occurrences
  i := 0;
  while i < a.Length
    invariant 0 <= i <= a.Length
    invariant forall val :: min <= val <= max ==>
      count[val - min] == multiset(a[..i])[val]
  {
    count[a[i] - min] := count[a[i] - min] + 1;
    i := i + 1;
  }

  // Reconstruct sorted array
  var index := 0;
  var val := min;
  while val <= max
    invariant min <= val <= max + 1
    invariant 0 <= index <= a.Length
    invariant forall v :: min <= v < val ==>
      multiset(a[..index])[v] == multiset(old(a[..]))[v]
    invariant index == sum(count[..(val - min)])
  {
    var j := 0;
    while j < count[val - min]
