      invariant index + j <= a.Length
      invariant forall k :: 0 <= k < index + j ==> 
        (k < index ==> a[k] < val) && (k >= index ==> a[k] == val)
    {
      a[index + j] := val;
      j := j + 1;
    }
    index := index + count[val - min];
    val := val + 1;
  }
}

