// Generic method to count elements in a sequence that satisfy a predicate
method CountIf<T(==)>(s: seq<T>, x: T, predicate: (T, T) -> bool) returns (count: nat)
  ensures count == |seq i | i in s && predicate(i, x)|
{
  count := 0;
  var i := 0;

  while i < |s|
    invariant 0 <= i <= |s|
    invariant count == |seq j | 0 <= j < i && predicate(s[j], x)|
  {
    if predicate(s[i], x) {
      count := count + 1;
    }
    i := i + 1;
  }
}

