  function CumulativeEvens(seq: seq<int>): seq<int>
    decreases |seq|
  {
    if |seq| == 0 then []
    else
      var rest := CumulativeEvens(seq[1..]);
      var current := CountEvens(seq[0..1]);
      [current] + (if |rest| == 0 then [] else [current + rest[0]] + rest[1..])
  }

  // Lemma about CumulativeEvens properties
  lemma CumulativeEvensProperties(seq: seq<int>)
    ensures |CumulativeEvens(seq)| == |seq|
    ensures |seq| > 0 ==> CumulativeEvens(seq)[0] == CountEvens(seq[0..1])
    ensures forall i :: 0 <= i < |seq| ==> 0 <= CumulativeEvens(seq)[i] <= i+1
    decreases |seq|
