  function CountEvens(seq: seq<int>): int
    decreases |seq|
  {
    if |seq| == 0 then 0
    else (if seq[0] % 2 == 0 then 1 else 0) + CountEvens(seq[1..])
  }

  // Lemma to prove properties about CountEvens
  lemma CountEvensProperties(seq: seq<int>)
    ensures 0 <= CountEvens(seq) <= |seq|
    decreases |seq|
